  stagePath(list) {
    const narrow = this.state.isNarrow, mid = this.state.isCompact && !narrow;
    return list.map((s, i) => {
      const up = !narrow && (i % 2 === 0);
      const col = narrow ? 'auto' : (mid ? (i % 6) + 1 : i + 1);
      const row = narrow ? 'auto' : (mid ? Math.floor(i / 6) + 1 : 1);
      const slugs = ['starting', 'married', 'havingkids', 'raising', 'collegeplan', 'upsdowns', 'collegepay', 'retiring', 'grownkids', 'inretirement', 'legacy'];
      const svg = { __html: this.stageIcons()[slugs[i]] || '' };
      return { ...s, svg,
        pos: narrow
          ? { position: 'relative', display: 'flex', flexDirection: 'row', alignItems: 'flex-start', gap: 14, textAlign: 'left', background: 'none', border: 0, padding: '0 0 26px 0', cursor: 'pointer', marginLeft: -21 }
          : { position: 'relative', display: 'grid', gridTemplateRows: 'minmax(0, 1fr) 44px minmax(0, 1fr)', justifyItems: 'center', textAlign: 'center', background: mid ? 'linear-gradient(var(--csi-light-blue-24), var(--csi-light-blue-24)) center / 100% 2px no-repeat' : 'none', border: 0, padding: '0 4px', cursor: 'pointer', gridColumn: col, gridRow: row, alignSelf: 'stretch', rowGap: 12 },
        dot: { position: 'relative', gridRow: narrow ? 'auto' : 2, alignSelf: narrow ? 'flex-start' : 'center', flex: '0 0 auto', width: 44, height: 44, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 12, letterSpacing: '0.02em', background: 'var(--csi-navy)', color: 'var(--csi-white)', border: '2px solid var(--csi-light-blue)', boxShadow: '0 0 0 5px var(--csi-white), 0 6px 14px rgba(30,58,95,0.2)', zIndex: 1 },
        txt: narrow ? { display: 'grid', gap: 4, textAlign: 'left', paddingTop: 8 } : { display: 'grid', gap: 4, textAlign: 'center', gridRow: up ? 1 : 3, alignSelf: up ? 'end' : 'start' }
      };
    });
  }

  stageList() {
    return [['01', 'Just starting out', 'starting'], ['02', 'Getting married', 'married'], ['03', 'Having kids', 'havingkids'], ['04', 'Raising your kids', 'raising'], ['05', 'Thinking about college', 'collegeplan'], ['06', 'Good years and hard ones', 'upsdowns'], ['07', 'Paying for college', 'collegepay'], ['08', 'Heading into retirement', 'retiring'], ['09', 'Grown children', 'grownkids'], ['10', 'Living in retirement', 'inretirement'], ['11', 'Legacy and later life', 'legacy']]
      .map(([n, label, slug]) => ({ n, label, slug, svg: { __html: this.stageIcons()[slug] }, go: this.go('audience', slug) }));
  }

  audNeighbors(slug) {
    const list = this.stageList();
    const k = list.findIndex((x) => x.slug === slug);
    if (k < 0) {
      const prof = { parents: ['married', 'havingkids', 'collegeplan'], preretire: ['retiring', 'grownkids'], seniors: ['inretirement', 'legacy'] }[slug] || [];
      return prof.map((s) => list.find((x) => x.slug === s)).map((x) => ({ label: x.n + ' · ' + x.label, go: x.go }));
    }
    const out = [];
    if (k > 0) out.push({ label: '‹ ' + list[k - 1].n + ' · ' + list[k - 1].label, go: list[k - 1].go });
    if (k < list.length - 1) out.push({ label: list[k + 1].n + ' · ' + list[k + 1].label + ' ›', go: list[k + 1].go });
    return out;
  }

