{" "}
<img src={"/photos/history-1.png"} alt={"The original Greco Brokerage Corp. storefront in Brooklyn"} width={"200"} height={"200"} style={{ "width": "200px", "height": "200px", "flex": "0 0 auto", "objectFit": "cover", "borderRadius": "12px", "display": "block" }} />
